import{_ as t,o as e,c as s,a2 as i}from"./chunks/framework.doxMM-x8.js";const k=JSON.parse('{"title":"快速开始","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/getting-started/quickstart","contentType":"guide","prev":{"text":"项目文档","link":"/docs/"},"next":{"text":"Lab 与资产库","link":"/guides/lab-viewer"}},"headers":[],"relativePath":"getting-started/quickstart.md","filePath":"getting-started/quickstart.md"}'),l={name:"getting-started/quickstart.md"};function r(h,a,d,n,p,o){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>目标：从源码启动 Lab Word 现有应用，并用 HTTP 和 Web 页面确认开发环境可用。已验证的 Viewer 体验目前来自<a href="./../guides/lab-viewer">独立预览</a>，正式 Lab 集成验收另行记录。</p><h2 id="_1-安装并启动" tabindex="-1">1. 安装并启动 <a class="header-anchor" href="#_1-安装并启动" aria-label="Permalink to &quot;1. 安装并启动&quot;">​</a></h2><p>安装 Docker 和 Compose。使用以下工具版本：</p><table tabindex="0"><thead><tr><th>工具</th><th>版本</th><th>来源</th></tr></thead><tbody><tr><td>Rust</td><td>1.96.0</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/d3878fce37705052c5cb5eef09ce25a958395af7/rust-toolchain.toml" target="_blank" rel="noreferrer">工具链</a></td></tr><tr><td>Node</td><td>24.18.0</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/d3878fce37705052c5cb5eef09ce25a958395af7/.node-version" target="_blank" rel="noreferrer">Node 版本</a></td></tr><tr><td>pnpm</td><td>11.17.0</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/d3878fce37705052c5cb5eef09ce25a958395af7/package.json" target="_blank" rel="noreferrer">包配置</a></td></tr><tr><td>just</td><td>1.58.0</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/d3878fce37705052c5cb5eef09ce25a958395af7/.tool-versions" target="_blank" rel="noreferrer">工具版本</a></td></tr></tbody></table><p>执行以下命令克隆仓库并启动开发环境：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/CaiZongyuan/labworld.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> labworld</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>项目命令在仓库根目录执行。首次启动下载依赖并编译 Rust。开发脚本启动 PostgreSQL、Redis、RustFS 和 Mailpit。随后执行迁移并初始化存储，再运行 API、Worker 和 Web。脚本会在本地开发卷写入数据。</p><p>默认设置来自 <a href="https://github.com/CaiZongyuan/labworld/blob/d3878fce37705052c5cb5eef09ce25a958395af7/.env.example" target="_blank" rel="noreferrer">.env.example</a>；需要调整时建立未跟踪的 <code>.env</code>。API 配置见<a href="./../reference/config">生成参考</a>。</p><h2 id="_2-观察结果" tabindex="-1">2. 观察结果 <a class="header-anchor" href="#_2-观察结果" aria-label="Permalink to &quot;2. 观察结果&quot;">​</a></h2><p>保持开发入口运行，在另一个终端执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/live</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/ready</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/api/v1/system/status</span></span></code></pre></div><p>预期每个响应均为 HTTP 200，并含 <code>x-request-id</code>。</p><table tabindex="0"><thead><tr><th>接口</th><th>预期信息</th></tr></thead><tbody><tr><td><code>/health/live</code></td><td>API 进程正在运行。</td></tr><tr><td><code>/health/ready</code></td><td>依赖与迁移已就绪。</td></tr><tr><td><code>/api/v1/system/status</code></td><td>当前系统状态。</td></tr></tbody></table><p>密码长度须为 12–128 字符。</p><ol><li>打开 <a href="http://127.0.0.1:5173/register" target="_blank" rel="noreferrer">http://127.0.0.1:5173/register</a>。</li><li>创建开发账号。</li></ol><p>首个账号为 Owner，后续账号为 Member。开发邮件在 <a href="http://127.0.0.1:8025" target="_blank" rel="noreferrer">http://127.0.0.1:8025</a> 查看。</p><p>已有平台可以验证登录与业务操作。Lab 体验以相应版本的集成验收为准。</p><h2 id="_3-检查依赖失败与恢复" tabindex="-1">3. 检查依赖失败与恢复 <a class="header-anchor" href="#_3-检查依赖失败与恢复" aria-label="Permalink to &quot;3. 检查依赖失败与恢复&quot;">​</a></h2><p>只在自己的开发环境执行本节失败检查。</p><ol><li>停止 PostgreSQL：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db-down</span></span></code></pre></div><ol start="2"><li>检查就绪状态：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/ready</span></span></code></pre></div><p><code>/health/ready</code> 应返回 503，<code>/health/live</code> 仍返回 200。</p><ol start="3"><li>启动 PostgreSQL：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wait</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span></span></code></pre></div><ol start="4"><li>再次检查就绪状态：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/ready</span></span></code></pre></div><p><code>/health/ready</code> 应恢复 200。</p><p>迁移不匹配时，先核对源码版本，再执行 <code>just migrate</code>。API 启动不自动迁移。</p><p>新增 SQL 迁移后：</p><ol><li>执行 <code>just migrate</code>。</li><li>重启开发入口。</li></ol><p>重启会更新二进制中的迁移集合。</p><h2 id="停止与下一步" tabindex="-1">停止与下一步 <a class="header-anchor" href="#停止与下一步" aria-label="Permalink to &quot;停止与下一步&quot;">​</a></h2><p>按 <code>Ctrl+C</code> 停止 API、Worker 和 Web。执行 <code>just services-down</code> 停止容器；此命令保留开发卷。</p><p>API 端口变更时，调整 <code>APP_BIND</code>，并将 <code>VITE_API_PROXY</code> 指向该 API 的可访问地址。Web 地址变更时，将 <code>APP_ORIGIN</code> 设为浏览器访问 Web 时的来源地址，包含协议、主机和端口。数据库端口变更时，同时调整 <code>POSTGRES_PORT</code> 和 <code>DATABASE_URL</code>。</p><p>接下来<a href="./../guides/lab-viewer">运行 Lab Viewer 预览</a>，或阅读<a href="./../architecture/project-structure">项目结构</a>。</p><p>查看在线文档：</p><ol><li>在仓库根目录执行 <code>just docs</code>。</li><li>打开 <a href="http://127.0.0.1:5174/labworld/docs/" target="_blank" rel="noreferrer">http://127.0.0.1:5174/labworld/docs/</a>。</li></ol><hr><p>源码版本：<code>d3878fce3770</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/d3878fce37705052c5cb5eef09ce25a958395af7/docs/getting-started/quickstart.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,42)])])}const b=t(l,[["render",r]]);export{k as __pageData,b as default};
